"""Load docker/cluster.yml and render each node's docker/node/.env."""

from __future__ import annotations

import importlib.util
import re
from dataclasses import dataclass, field
from functools import cache
from pathlib import Path
from types import ModuleType

import yaml

REPO_ROOT = Path(__file__).resolve().parent.parent
CLUSTER_FILE = REPO_ROOT / "docker" / "cluster.yml"
LAUNCH_PY = REPO_ROOT / "docker" / "config" / "launch.py"
NODE_DIR = "docker/node"  # relative to repo_path on each node

ENV_HEADER = (
    "# GENERATED by `spark-cluster sync` from docker/cluster.yml. Do not edit:\n"
    "# change cluster.yml and run `uv run spark-cluster sync` on the control machine.\n"
)

# Written by spark-cluster for each node; cluster.yml must not set them.
DERIVED_KEYS = (
    "NODE_NAME",
    "CONTAINER_NAME",
    "VLLM_HOST_IP",
    "CLUSTER_NNODES",
    "CLUSTER_NODE_RANK",
    "CLUSTER_MASTER_ADDR",
    "CLUSTER_MASTER_PORT",
)
# PyTorch reads these names; the launcher uses CLUSTER_* instead.
FORBIDDEN_KEYS = ("MASTER_ADDR", "MASTER_PORT", "RANK", "WORLD_SIZE")


class ConfigError(Exception):
    pass


@dataclass
class Node:
    name: str
    ssh: str
    mesh_ip: str
    rank: int
    env: dict[str, str] = field(default_factory=dict)

    @property
    def is_head(self) -> bool:
        return self.rank == 0

    @property
    def container(self) -> str:
        return "vllm-server" if self.is_head else "vllm-worker"


@dataclass
class Cluster:
    repo_path: str
    api_url: str
    master_port: int
    env: dict[str, str]
    nodes: list[Node]
    path: Path
    evals_path: str | None = None  # private evaluation suite on the head (spark-cluster eval)

    @property
    def head(self) -> Node:
        return self.nodes[0]

    @property
    def model_name(self) -> str:
        return self.env["MODEL_NAME"]

    @property
    def image(self) -> str:
        return self.env["VLLM_IMAGE"]

    def node(self, name: str) -> Node:
        for n in self.nodes:
            if n.name == name:
                return n
        raise ConfigError(f"no node named {name!r} (nodes: {', '.join(n.name for n in self.nodes)})")

    def node_dir(self) -> str:
        """docker/node on the nodes, for use in remote shell commands (`~` stays unquoted)."""
        return f"{self.repo_path.rstrip('/')}/{NODE_DIR}"


def _env_map(raw, where: str) -> dict[str, str]:
    if raw is None:
        return {}
    if not isinstance(raw, dict):
        raise ConfigError(f"{where}: env must be a mapping")
    env = {}
    for key, value in raw.items():
        if key in DERIVED_KEYS:
            raise ConfigError(f"{where}: {key} is set by spark-cluster for each node; remove it")
        if key in FORBIDDEN_KEYS:
            raise ConfigError(f"{where}: {key} is read by PyTorch; the launcher uses CLUSTER_* instead")
        if value is None or isinstance(value, (dict, list)):
            raise ConfigError(f"{where}: {key} must be a plain value")
        if isinstance(value, bool):
            value = "1" if value else "0"
        env[str(key)] = str(value)
    return env


def load_cluster(path: Path = CLUSTER_FILE) -> Cluster:
    try:
        data = yaml.safe_load(path.read_text())
    except FileNotFoundError:
        raise ConfigError(f"{path} not found") from None
    except yaml.YAMLError as e:
        raise ConfigError(f"{path}: {e}") from None

    for key in ("repo_path", "api_url", "env", "nodes"):
        if key not in data:
            raise ConfigError(f"{path}: missing {key!r}")

    env = _env_map(data["env"], "env")
    for key in ("MODEL_NAME", "VLLM_IMAGE", "VLLM_ENTRYPOINT", "HF_HOME"):
        if key not in env:
            raise ConfigError(f"{path}: env.{key} is required")

    nodes = []
    for rank, raw in enumerate(data["nodes"] or []):
        for key in ("name", "ssh", "mesh_ip"):
            if key not in raw:
                raise ConfigError(f"{path}: node #{rank} is missing {key!r}")
        nodes.append(
            Node(
                name=raw["name"],
                ssh=raw["ssh"],
                mesh_ip=raw["mesh_ip"],
                rank=rank,
                env=_env_map(raw.get("env"), f"node {raw['name']}"),
            )
        )
    if not nodes:
        raise ConfigError(f"{path}: no nodes")
    names = [n.name for n in nodes]
    if len(set(names)) != len(names):
        raise ConfigError(f"{path}: node names must be unique")

    return Cluster(
        repo_path=str(data["repo_path"]),
        api_url=str(data["api_url"]).rstrip("/"),
        master_port=int(data.get("master_port", 29501)),
        env=env,
        nodes=nodes,
        path=path,
        evals_path=str(data["evals_path"]).rstrip("/") if data.get("evals_path") else None,
    )


def node_env(cluster: Cluster, node: Node) -> dict[str, str]:
    """Everything that goes into a node's .env: derived values, shared env, then node overrides."""
    env = {
        "NODE_NAME": node.name,
        "CONTAINER_NAME": node.container,
        "VLLM_HOST_IP": node.mesh_ip,
        "CLUSTER_NNODES": str(len(cluster.nodes)),
        "CLUSTER_NODE_RANK": str(node.rank),
        "CLUSTER_MASTER_ADDR": cluster.head.mesh_ip,
        "CLUSTER_MASTER_PORT": str(cluster.master_port),
    }
    env.update(cluster.env)
    env.update(node.env)
    return env


def render_env(cluster: Cluster, node: Node) -> str:
    lines = [f"{k}={v}" for k, v in node_env(cluster, node).items()]
    return ENV_HEADER + "\n".join(lines) + "\n"


_MODEL_LINE = re.compile(r"^(\s+MODEL_NAME:\s*)(\S+)(.*)$", re.MULTILINE)


def set_model_name(text: str, model_name: str) -> str:
    """Rewrite only the MODEL_NAME: line of cluster.yml, keeping its comments."""
    new, count = _MODEL_LINE.subn(lambda m: m.group(1) + model_name + m.group(3), text, count=1)
    if count != 1:
        raise ConfigError("no `MODEL_NAME:` line found in cluster.yml")
    return new


@cache
def launch_module() -> ModuleType:
    """docker/config/launch.py, loaded by path (it must stay a standalone file for the container)."""
    spec = importlib.util.spec_from_file_location("mixvllm_launch", LAUNCH_PY)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def load_registry() -> dict:
    return launch_module().load_registry()


def model_config(registry: dict, model_name: str) -> dict | None:
    """The registry entry, or None if the name isn't there (launch.get_model_config exits instead)."""
    if model_name not in registry.get("models", {}):
        return None
    return launch_module().get_model_config(registry, model_name)
